arguments.new_str:
class EnvVarCheck
{
    void CheckFlag()
    {
        // On Linux, set via: export MY_FLAG=""
        // .NET 9 breaking change: empty env vars are no longer treated as unset.
        // Use a dedicated method to distinguish "not set" from "explicitly empty".
        var val = Environment.GetEnvironmentVariable("MY_FLAG");
        if (!IsEnvironmentVariableSet("MY_FLAG"))
        {
            Console.WriteLine("MY_FLAG not set, using default");
        }
    }

    private static bool IsEnvironmentVariableSet(string variable)
    {
        // In .NET 9, GetEnvironmentVariable returns "" for empty vars (previously null).
        // Check the process environment directly to distinguish missing from empty.
        var vars = Environment.GetEnvironmentVariables();
        return vars.Contains(variable);
    }
}

